pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(name) = bytes.strip_prefix("v:2|hello:") {
        return Ok(Msg::Hello(name.into()));
    }
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!("v:2|hello:{name}"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn ping_encode_roundtrip() {
        assert!(matches!(decode(&encode(&Msg::Ping)), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_roundtrips_through_v2_encoding() {
        let msg = Msg::Hello("world".into());
        assert!(matches!(decode(&encode(&msg)), Ok(Msg::Hello(name)) if name == "world"));
        assert_eq!(encode(&msg), "v:2|hello:world");
    }
}
